#!/usr/bin/env bash
# shellcheck source-path=SCRIPTDIR
# shellcheck disable=SC2001
# resolve-release-gav.sh — Resolve the release GAV from pom.xml (strip -SNAPSHOT) and write build-metadata.json for PROD.
#
# GENERATED by tests/parity/extract_inline_bash.py — do not hand-edit (change the Azure source or
# the extractor, then run it with --write). Extracted from the Azure DevOps inline step:
#   source : platforms/azure-devops/mulesoft-pipeline-templates/pipelines/templates/stages/resolve-version.yml
#   step   : "Resolve Release GAV" (Bash@3 inline)
# The body is that step verbatim, except: ##vso commands -> ci-shim calls, Azure predefined
# variables -> ci-shim normalizers, and $(...) / ${{ parameters.* }} macros -> the MDF_* inputs below.
# The shellcheck codes disabled above come from constructs inherited verbatim from that source.
#
# Outputs: GROUP_ID (output), ARTIFACT_ID (output), VERSION (output)

# shellcheck source=lib/ci-shim.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/ci-shim.sh"

# >>> extracted body
set -euo pipefail
SOURCE_POM="$(ci_default_working_directory)/pom.xml"

echo "[DEBUG] ============================================"
echo "[DEBUG] RESOLVE RELEASE VERSION"
echo "[DEBUG] ============================================"

if [[ ! -f "$SOURCE_POM" ]]; then
  ci_log_error "pom.xml not found at $SOURCE_POM"
  exit 1
fi

# Extract top-level GAV from pom.xml using grep/sed (skip <parent> block)
PARENT_END_LINE=$(grep -n '</parent>' "$SOURCE_POM" | head -1 | cut -d: -f1)
if [[ -n "$PARENT_END_LINE" ]]; then
  SEARCH_CONTENT=$(tail -n +"$((PARENT_END_LINE + 1))" "$SOURCE_POM")
else
  SEARCH_CONTENT=$(cat "$SOURCE_POM")
fi

GROUP_ID=$(echo "$SEARCH_CONTENT" | grep '<groupId>' | head -1 | sed 's/.*<groupId>\(.*\)<\/groupId>.*/\1/' | tr -d '[:space:]')
ARTIFACT_ID=$(echo "$SEARCH_CONTENT" | grep '<artifactId>' | head -1 | sed 's/.*<artifactId>\(.*\)<\/artifactId>.*/\1/' | tr -d '[:space:]')
CURRENT_VERSION=$(echo "$SEARCH_CONTENT" | grep '<version>' | head -1 | sed 's/.*<version>\(.*\)<\/version>.*/\1/' | tr -d '[:space:]')

if [[ -z "$GROUP_ID" || -z "$ARTIFACT_ID" || -z "$CURRENT_VERSION" ]]; then
  ci_log_error "Failed to resolve GAV from pom.xml."
  echo "[DEBUG] groupId=$GROUP_ID, artifactId=$ARTIFACT_ID, version=$CURRENT_VERSION"
  exit 1
fi

RELEASE_VERSION=$(echo "$CURRENT_VERSION" | sed 's/-SNAPSHOT//')
echo "[DEBUG] Resolved: ${GROUP_ID}:${ARTIFACT_ID}:${CURRENT_VERSION} -> release ${RELEASE_VERSION}"

# Extract RAML dependency coordinates (same logic as build step)
RAML_GROUP_ID=""
RAML_ARTIFACT_ID=""
RAML_VERSION=""
RAML_BLOCK=$(awk '/<dependency>/{block=""} {block=block $0 "\n"} /<\/dependency>/{if (block ~ /<classifier>raml<\/classifier>/) print block}' "$SOURCE_POM")
if [[ -n "$RAML_BLOCK" ]]; then
  RAML_GROUP_ID=$(echo "$RAML_BLOCK" | grep '<groupId>' | sed 's/.*<groupId>\(.*\)<\/groupId>.*/\1/' | tr -d '[:space:]')
  RAML_ARTIFACT_ID=$(echo "$RAML_BLOCK" | grep '<artifactId>' | sed 's/.*<artifactId>\(.*\)<\/artifactId>.*/\1/' | tr -d '[:space:]')
  RAML_VERSION=$(echo "$RAML_BLOCK" | grep '<version>' | sed 's/.*<version>\(.*\)<\/version>.*/\1/' | tr -d '[:space:]')
  echo "[DEBUG] RAML dependency: ${RAML_GROUP_ID}:${RAML_ARTIFACT_ID}:${RAML_VERSION}"
else
  echo "[DEBUG] No RAML dependency found in pom.xml"
fi

# Generate build-metadata.json (same structure as build stage)
METADATA_DIR="$(ci_artifact_staging_dir)/build-metadata"
mkdir -p "$METADATA_DIR"

{
  echo '{'
  echo "  \"groupId\": \"$GROUP_ID\","
  echo "  \"artifactId\": \"$ARTIFACT_ID\","
  echo "  \"version\": \"$RELEASE_VERSION\","
  echo "  \"classifier\": \"mule-application\","
  echo "  \"ramlGroupId\": \"$RAML_GROUP_ID\","
  echo "  \"ramlArtifactId\": \"$RAML_ARTIFACT_ID\","
  echo "  \"ramlVersion\": \"$RAML_VERSION\","
  echo "  \"buildNumber\": \"$(ci_build_number)\","
  echo "  \"sourceBranch\": \"$(ci_source_branch)\","
  echo "  \"commitId\": \"$(ci_commit_sha)\""
  echo '}'
} > "$METADATA_DIR/build-metadata.json"

echo "[DEBUG] build-metadata.json:"
echo "[DEBUG] $(cat "$METADATA_DIR/build-metadata.json")"

ci_set_var GROUP_ID "$GROUP_ID"
ci_set_var ARTIFACT_ID "$ARTIFACT_ID"
ci_set_var VERSION "$RELEASE_VERSION"
echo "[DEBUG] RESOLVE RELEASE VERSION COMPLETE"
# <<< extracted body
